// Decides whether this event starts a mission, continues one, or is none of our business.
//
// The loop this sits in is: the mod reports something -> the model picks the next high-level
// command -> the mod carries it out and reports again. Every guard here exists to make sure
// that loop can always end.
const event = $json;
const cfg = $('Config').first().json;
const maxSteps = Number(cfg.maxSteps || 12);

const store = $getWorkflowStaticData('global');
store.missions = store.missions || {};
const now = Date.now();

// A mission that has gone quiet is over, whatever happened to it. Without this a drone that
// dropped off mid-flight would keep its step count forever and never fly again.
for (const [id, m] of Object.entries(store.missions)) {
  if (now - m.updated > 15 * 60 * 1000) delete store.missions[id];
}

const name = event.event;
const droneId = event.drone_id;

const STARTS = ['fire_detected', 'disaster_detected'];
// Everything the mod reports when a command it was given has run its course.
const CONTINUES = ['drone_arrived', 'drone_stuck', 'command_failed', 'water_dispensed', 'drone_damaged'];

if (STARTS.includes(name)) {
  return [{ json: {
    action: 'dispatch',
    event: name,
    location: event.location,
    reason: `${event.hazard || 'fire'} of ${event.size || '?'} blocks reported by ${droneId} `
          + `(${event.severity || 'unknown'} severity, ${event.terrain || 'unknown terrain'})`,
  } }];
}

if (!CONTINUES.includes(name)) {
  return [];                       // spawned, removed, offline: nothing to decide
}

const mission = store.missions[droneId];
if (!mission) {
  return [];                       // this drone is not on a mission of ours - patrol, or a human
}

// Arriving home, or being told to hold, is how a mission ends.
if (name === 'drone_arrived' && (event.command === 'return_home' || event.command === 'hover')) {
  delete store.missions[droneId];
  return [];
}

mission.steps += 1;
mission.updated = now;

// Two steps past the budget the model has had its chance; stop rather than keep paying for it.
if (mission.steps > maxSteps + 2) {
  delete store.missions[droneId];
  return [];
}

return [{ json: {
  action: 'assess',
  event: name,
  drone_id: droneId,
  step: mission.steps,
  mustFinish: mission.steps > maxSteps,
  reason: mission.reason,
  lastOutcome: {
    event: name,
    command: event.command || null,
    reason: event.reason || null,
    extinguished: event.extinguished ?? null,
    hazard: event.hazard || null,
  },
} }];

// The mod picked the drone, because it is the only side that knows where they all are.
const reply = $json;
const plan = $('Plan').first().json;

if (!reply || reply.dispatched !== true) {
  // Nobody free. The mod re-reports a fire once its cooldown lapses, so this is a pause,
  // not a loss - but it is worth seeing in the execution log.
  console.log('no drone available for:', plan.reason);
  return [];
}

const store = $getWorkflowStaticData('global');
store.missions = store.missions || {};
store.missions[reply.drone_id] = { steps: 1, updated: Date.now(), reason: plan.reason };

return [{ json: {
  action: 'assess',
  event: plan.event,
  drone_id: reply.drone_id,
  step: 1,
  mustFinish: false,
  reason: plan.reason,
  lastOutcome: { event: 'dispatched', command: 'move_to', reason: null },
} }];

// Builds the one request the model sees. Everything it needs is already a fact: the mod did
// the perceiving, so there is no image, no raw block data, and nothing to count.
const state = $('Mission').first().json;      // the join point, so this works on either branch
const view = $('Look around').first().json;
const fleet = $json && Array.isArray($json.drones) ? $json : { drones: [] };
const cfg = $('Config').first().json;

if (!view || !view.environment) {
  // The perception call failed - a tunnel that dropped, a drone that was removed mid-mission.
  // Stopping is better than asking a model to reason about an error object.
  console.log('no perception for', state.drone_id, JSON.stringify(view).slice(0, 300));
  return [];
}

const system = [
  'You command a firefighting drone inside Minecraft. You choose ONE high-level command at a time.',
  'The mod flies the drone for you: it handles pathfinding, obstacle avoidance and collision.',
  'Never think about frame-by-frame movement. Never invent coordinates you were not given.',
  '',
  'Reply with JSON only, in this exact shape:',
  '{"reasoning": "<one short sentence>", "command": { ... }}',
  '',
  'The command must be exactly one of:',
  '  {"command":"move","direction":"north|northeast|east|southeast|south|southwest|west|northwest|up|down","distance":<1-32>}',
  '  {"command":"move_to","x":<n>,"y":<n>,"z":<n>}',
  '  {"command":"dispense_water","radius":<1-8>}   // puts out fire on the ground BELOW the drone',
  '  {"command":"return_home"}                     // ends the mission',
  '  {"command":"hover"}                           // ends the mission, holding position',
  '',
  'How to fight a fire:',
  '  1. Get above it. dispense_water only affects the ground directly beneath the drone,',
  '     so move_to the hazard position with y set 4-8 blocks ABOVE the hazard.',
  '  2. dispense_water. A radius of 3-5 covers most fires.',
  '  3. Look at the next perception. If hazards are gone, return_home. If fire remains,',
  '     move over the nearest remaining hazard and drop again.',
  '  4. If the last command failed with "no fire within N blocks", you are not over it:',
  '     move_to the hazard position again, or raise the radius.',
  '  5. If the drone is stuck, move up 6-10 blocks first, then try again from higher up.',
  '',
  'Reading the perception:',
  '  - "hazards", "obstacles" and "resources" give a direction, a distance and a real position.',
  '  - "clearance" is how many blocks are free each way at the drone\'s own altitude.',
  '  - "local_map.grid" is a top-down picture: north is the top row, east is right, D is you.',
  '  - "altitude_above_ground" is how high you are; stay above 3 unless dropping water.',
].join('\n');

const user = {
  mission: state.reason,
  step: state.step,
  step_budget: Number(cfg.maxSteps || 12),
  must_finish_now: state.mustFinish === true,
  what_just_happened: state.lastOutcome,
  drone: view,
  other_drones: (fleet.drones || [])
    .filter(d => d.id !== state.drone_id)
    .map(d => ({ id: d.id, status: d.status, position: d.position })),
};

const instruction = state.mustFinish
  ? 'You have used your step budget. Reply with return_home or hover and nothing else.'
  : 'Choose the single best next command.';

return [{ json: {
  drone_id: state.drone_id,
  body: {
    model: cfg.llmModel,
    temperature: 0.1,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: instruction + '\n\n' + JSON.stringify(user, null, 1) },
    ],
  },
} }];

// The model is untrusted input: anything it sends that is not one of the five commands is
// dropped rather than forwarded to a server that can set blocks on fire.
const ALLOWED = ['move', 'move_to', 'dispense_water', 'return_home', 'hover'];
const DIRECTIONS = ['north','northeast','east','southeast','south','southwest','west','northwest','up','down'];

const droneId = $('Build prompt').first().json.drone_id;
const reply = $json;

let text = reply?.choices?.[0]?.message?.content;
if (typeof text !== 'string' || !text.trim()) {
  console.log('model returned nothing usable:', JSON.stringify(reply).slice(0, 400));
  return [];
}

// Models fence their JSON often enough that stripping it is cheaper than re-prompting.
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let decision;
try {
  decision = JSON.parse(text);
} catch (e) {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) { console.log('model did not return JSON:', text.slice(0, 300)); return []; }
  try { decision = JSON.parse(match[0]); }
  catch (e2) { console.log('model JSON did not parse:', text.slice(0, 300)); return []; }
}

const command = decision.command;
if (!command || !ALLOWED.includes(command.command)) {
  console.log('rejected command:', JSON.stringify(command));
  return [];
}

// Normalise the arguments the mod would reject anyway, so a near-miss still flies.
if (command.command === 'move') {
  if (!DIRECTIONS.includes(String(command.direction || '').toLowerCase())) {
    console.log('rejected direction:', command.direction); return [];
  }
  command.direction = String(command.direction).toLowerCase();
  command.distance = Math.max(1, Math.min(32, Number(command.distance) || 5));
}
if (command.command === 'move_to') {
  for (const axis of ['x', 'y', 'z']) {
    if (!Number.isFinite(Number(command[axis]))) { console.log('move_to missing', axis); return []; }
    command[axis] = Number(command[axis]);
  }
}
if (command.command === 'dispense_water') {
  command.radius = Math.max(1, Math.min(8, Number(command.radius) || 4));
}

// hover ends the mission here: unlike the others it finishes instantly and reports nothing,
// so nothing would ever come back to close the loop.
if (command.command === 'hover') {
  const store = $getWorkflowStaticData('global');
  if (store.missions) delete store.missions[droneId];
}

return [{ json: { drone_id: droneId, command, reasoning: decision.reasoning || '' } }];
